from moe_gumbel_gate_hybrid import build_network, create_optimizer as make_optimizer

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'd_model': 256,
        'num_blocks': 5,
        'dilations': [1,2,4,8,16],
        'kernel_size': 7,
        'dropout_rate': 0.1,
        'positional_encoding': False,
        'tau': 0.25,
        'gru_hidden_dim': 256,
        'gumbel_temp': 0.5
    }

def create_network(hparams):
    return build_network(hparams.get('d_output', 1),
                         hparams.get('task_type', 'regression'),
                         hparams)

def create_optimizer(learning_rate: float = 0.001):
    return make_optimizer(learning_rate)

